Debug the authentication flow (app/auth/callback/route.ts), moderation engine (lib/moderation.ts), and multi-account storage (lib/savedAccounts.ts).

Here is app/auth/callback/route.ts:
```typescript
import { NextResponse, type NextRequest } from 'next/server'
import { createSupabaseServerClient } from '@/lib/supabase/server'
import { LOGGED_IN_HOME, POST_SIGNUP_ROUTE } from '@/constants'
export const dynamic = 'force-dynamic'
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const code = searchParams.get('code')
  const next = searchParams.get('next')
  if (!code) return NextResponse.redirect(new URL('/login', request.url))
  const supabase = await createSupabaseServerClient()
  const { data: sessionData, error } = await supabase.auth.exchangeCodeForSession(code)
  if (error || !sessionData.session) return NextResponse.redirect(new URL('/login?error=oauth', request.url))
  const userId = sessionData.session.user.id
  const userEmail = sessionData.session.user.email ?? ''
  const { data: profile } = await supabase.from('profiles').select('state, name').eq('id', userId).maybeSingle()
  const hasRegion = Boolean(profile?.state)
  if (!hasRegion) return NextResponse.redirect(new URL(POST_SIGNUP_ROUTE, request.url))
  const confirmUrl = new URL('/login', request.url)
  confirmUrl.searchParams.set('google_confirm', 'true')
  if (userEmail) confirmUrl.searchParams.set('email', userEmail)
  if (profile?.name) confirmUrl.searchParams.set('name', profile.name)
  if (next && next.startsWith('/') && !next.startsWith('//') && !next.startsWith('/\\')) {
    confirmUrl.searchParams.set('next', next)
  }
  return NextResponse.redirect(confirmUrl)
}
```

Specifically verify: 1. Is the OAuth 'next' redirect parameter completely safe from all bypass variations (backslash, protocol-relative, encoded schemes)? 2. Can anonymous post real author IDs leak via store or serialization? 3. Are banned users strictly barred from all mutations? Provide concrete fixes for any bugs found.
